    esgBullet2Title: "Net-sıfır kapasiteli üretim",
    esgBullet2Text: " — üretim hücresi güneşle çalışabilir ve tedarik zincirinizin yukarı akışındaki yenilenebilir enerji taahhütlerinizi destekler.",
    esgBullet3Title: "Sıfır yıkama atığı metalik salınım",
    esgBullet3Text: " — FUZE tasarım gereği sızıntısızdır. Bu finişin belediye su arıtma yüküne aşağı akış katkınız = 0.",
    esgBullet4Title: "PFAS içermez, formaldehit içermez, bağlayıcı içermez",
    esgBullet4Text: " — mevcutların gerektirdiği her petrokimyasal girdiyi FUZE ortadan kaldırır.",
    esgBullet5Title: "Mekanik ve kimyasal geri dönüşüm uyumlu",
    esgBullet5Text: " — işlenmiş ürünler, geri kazanılmış lif akışlarını kirletmeden döngüsellik programlarınıza yeniden girebilir.",
    esgBullet6Title: "ZDHC MRSL uyumlu",
    esgBullet6Text: " — işaretli madde yok. ZDHC Conformance Level 3 ile uyumlu.",
    methodologyEyebrow: "Metodoloji notu",
    methodologyTitle: "ASTM E2149 neden FUZE'nin birincil etkinlik testidir",
    methodologyPara1: "Marka sürdürülebilirlik ekipleri sıkça sorar: F3 ve F4 seviyelerinde FUZE birincil etkinlik testi neden AATCC 100 yerine ASTM E2149 altında raporlanır? Kısa cevap: ASTM E2149, sızıntısız temas-öldürme kimyası için tasarlanmış dinamik temas testidir. Bakteri hücresi ile metamateryal-bağlı lif yüzeyi arasındaki doğrudan fiziksel teması ödüllendirir — bu tam olarak FUZE'nin mekanizmasıdır.",
    methodologyPara2Lead: "AATCC 100, inoküle edilmiş kupon etrafında kumaş katmanları istifler ve hayatta kalan koloni oluşturan birimleri ölçer. ",
    methodologyPara2Em: "sızıntılı",
    methodologyPara2Suffix: " antimikrobiyaller için tasarlandı — çevre nemine iyon salan ve bakterileri bu iyon alanı aracılığıyla öldüren kimyalar. Katmanlı geometri sızıntılı kimyalara yardımcı olur; salınan iyonlar katmanlar arası alanı doyurur.",
    methodologyPara3: "FUZE, metamateryal yoğunluğunun test geometrisini aşmaya yeterli olduğu daha yüksek seviyelerde (F1 ve F2) AATCC 100'ü geçer. F3 ve F4 için uygun birincil etkinlik testi ASTM E2149'dur. Marka denetimleri, tüm dört seviyede ASTM E2149 ve tamamlayıcı bir görünüm olarak F1 ve F2'de AATCC 100 alır.",
    ctaBack: "← FUZE Temellerine Geri Dön",
    ctaStory: "FUZE Hikayesi →",
    ctaApplication: "Uygulama yöntemleri →",
    ctaSustainability: "Sürdürülebilirlik panosu →",
